def compute_grayscale_histogram(image_file):
    if not os.path.exists(image_file):
        raise FileNotFoundError(f"Image file '{image_file}' not found.")

    try:
        img = cv2.imread(image_file)
    except Exception as e:
        raise ValueError(f"Failed to read image: {e}")

    if img is None:
        raise ValueError("Invalid image file.")

    gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)

    histogram, _ = np.histogram(gray, bins=256, range=(0, 256))

    return histogram.astype(np.int64)

