import collections
import json
import os
from typing import Dict, Any

def count_json_keys(directory_path: str) -> Dict[str, int]:
    """
    Count the total appearances of all keys in all JSON files in the specified directory.

    Args:
        directory_path: Path to the directory containing JSON files.

    Returns:
        A dictionary mapping each key found in the JSON files to its total count.
    """
    counts: Dict[str, int] = collections.defaultdict(int)

    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            filepath = os.path.join(directory_path, filename)
            try:
                with open(filepath, 'r', encoding='utf-8') as f:
                    data: Any = json.load(f)
                    def collect_keys(obj: Any) -> None:
                        if isinstance(obj, dict):
                            for key in obj:
                                counts[key] += 1
                                collect_keys(obj[key])
                        elif isinstance(obj, list):
                            for item in obj:
                                collect_keys(item)
                    collect_keys(data)
            except json.JSONDecodeError:
                continue

    return dict(counts)

import string
import random

def transform_text(text: str, seed: int | None = None) -> str:
    """Transforms the input text by replacing each alphabetic character with a random letter,
    preserving case and non-alphabetic characters.

    Args:
        text: The input string to transform.
        seed: Optional seed value for reproducibility.

    Returns:
        A transformed string with random alphabetic replacements.
    """
    if seed is not None:
        random.seed(seed)
    transformed_chars: list[str] = []
    for char in text:
        if char.isupper():
            transformed_chars.append(random.choice(string.ascii_uppercase))
        elif char.islower():
            transformed_chars.append(random.choice(string.ascii_lowercase))
        else:
            transformed_chars.append(char)
    return ''.join(transformed_chars)

