def aggregate_and_sine(nested_dict):
    aggregated = {}
    def collect_values(d):
        for k, v in d.items():
            if k == 'ele':
                continue
            if isinstance(v, dict):
                collect_values(v)
            else:
                aggregated.setdefault(k, 0.0)
