    return dst_dir

import numpy as np
from scipy import stats

def find_mode(L):
    def flatten(nested):
        result = []
        for item in nested:
            if isinstance(item, list):
                result.extend(flatten(item))
            else:
                result.append(item)
        return result

    flattened = flatten(L)
    arr = np.array(flattened)
    mode_result = stats.mode(arr)
    return int(mode_result.mode[0])

