import numpy as np
from scipy import stats

def calculate_mode(L):
    # Flatten the nested list
    def flatten(nested):
        for item in nested:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    flat_list = list(flatten(L))
    if not flat_list:
        raise ValueError("Empty list has no mode")

    arr = np.array(flat_list)
    mode_result = stats.mode(arr)
    return int(mode_result.mode[0])

